47: /**
48:  * A factory for Unix domain sockets.
49:  * <p>
50:  * This implementation supports both the JDK16+ standard library implementation (JEP 380) and the JUnixSocket library.
51:  * It will automatically detect which implementation is available and use it; if both are available, the standard
52:  * library implementation is preferred.
53:  * </p>
54:  *
55:  * @since 5.6
56:  */
57: @Contract(threading = ThreadingBehavior.STATELESS)
58: @Internal
59: public final class UnixDomainSocketFactory {
60:     private static final Logger LOG = LoggerFactory.getLogger(UnixDomainSocketFactory.class);
61: 
62:     private static final String JDK_UNIX_SOCKET_ADDRESS_CLASS = "java.net.UnixDomainSocketAddress";
63:     private static final String JUNIXSOCKET_SOCKET_CLASS = "org.newsclub.net.unix.AFUNIXSocket";
64:     private static final String JUNIXSOCKET_ADDRESS_CLASS = "org.newsclub.net.unix.AFUNIXSocketAddress";
65: 
66:     private enum Implementation {
67:         JDK,
68:         JUNIXSOCKET,
69:         NONE
70:     }
71: 
72:     private static final Implementation IMPLEMENTATION = detectImplementation();
73: 
74:     private static Implementation detectImplementation() {
75:         try {
76:             Class.forName(JDK_UNIX_SOCKET_ADDRESS_CLASS);
77:             LOG.debug("Using JDK Unix Domain Socket implementation");
78:             return Implementation.JDK;
79:         } catch (final ClassNotFoundException e) {
80:             try {
81:                 Class.forName(JUNIXSOCKET_SOCKET_CLASS);
82:                 LOG.debug("Using JUnixSocket Unix Domain Socket implementation");
83:                 return Implementation.JUNIXSOCKET;
84:             } catch (final ClassNotFoundException e2) {
85:                 LOG.debug("No Unix Domain Socket implementation found");
86:                 return Implementation.NONE;
87:             }
88:         }
89:     }
90: 
91:     /**
92:      * Checks if Unix Domain Socket support is available.
93:      *
94:      * @return true if Unix Domain Socket support is available, false otherwise
95:      */
96:     public static boolean isAvailable() {
97:         return IMPLEMENTATION != Implementation.NONE;
98:     }
99: 
100:     /**
101:      * Default instance of {@link UnixDomainSocketFactory}.
102:      */
103:     private static final UnixDomainSocketFactory INSTANCE = new UnixDomainSocketFactory();
104: 
105:     /**
106:      * Gets the singleton instance of {@link UnixDomainSocketFactory}.
107:      *
108:      * @return the singleton instance
109:      */
110:     public static UnixDomainSocketFactory getSocketFactory() {
111:         return INSTANCE;
112:     }
113: 
114:     public SocketAddress createSocketAddress(final Path socketPath) {
115:         if (!isAvailable()) {
116:             throw new UnsupportedOperationException("Unix Domain Socket support is not available");
117:         }
118:         Args.notNull(socketPath, "Unix domain socket path");
119: 
120:         try {
121:             if (IMPLEMENTATION == Implementation.JDK) {
122:                 // JDK implementation
123:                 final Class<?> addressClass = Class.forName(JDK_UNIX_SOCKET_ADDRESS_CLASS);
124:                 final Method ofMethod = addressClass.getMethod("of", Path.class);
125:                 return (SocketAddress) ofMethod.invoke(null, socketPath);
126:             } else {
127:                 // JUnixSocket implementation
128:                 final Class<?> addressClass = Class.forName(JUNIXSOCKET_ADDRESS_CLASS);
129:                 final Method ofMethod = addressClass.getMethod("of", Path.class);
130:                 return (SocketAddress) ofMethod.invoke(null, socketPath);
131:             }
132:         } catch (final ReflectiveOperationException ex) {
133:             throw new RuntimeException("Could not create UDS SocketAddress", ex);
134:         }
135:     }
136: 
137:     public Socket createSocket() throws IOException {
138:         if (!isAvailable()) {
139:             throw new UnsupportedOperationException("Unix Domain Socket support is not available");
140:         }
141: 
142:         try {
143:             if (IMPLEMENTATION == Implementation.JDK) {
144:                 // Java 16+ only supports UDS through the SocketChannel API, but the sync client is coupled to the
145:                 // legacy Socket API. To facilitate this, we use an adapter, similar to the one provided by JUnixSocket.
146:                 try {
147:                     final SocketChannel channel = (SocketChannel) SocketChannel.class.getMethod("open",
148:                             ProtocolFamily.class)
149:                         .invoke(null, StandardProtocolFamily.valueOf("UNIX"));
150:                     return new Jep380SocketChannelAdapter(channel);
151:                 } catch (final ReflectiveOperationException ex) {
152:                     throw new UnsupportedOperationException("JEP 380 Unix domain sockets are not supported; use "
153:                         + "JUnixSocket", ex);
154:                 }
155:             } else {
156:                 // JUnixSocket implementation
157:                 final Class<?> socketClass = Class.forName(JUNIXSOCKET_SOCKET_CLASS);
158:                 final Method newInstanceMethod = socketClass.getMethod("newInstance");
159:                 return (Socket) newInstanceMethod.invoke(null);
160:             }
161:         } catch (final Exception e) {
162:             throw new IOException("Failed to create Unix domain socket", e);
163:         }
164:     }
165: 
166:     public Socket connectSocket(
167:         final Socket socket,
168:         final Path socketPath,
169:         final TimeValue connectTimeout
170:     ) throws IOException {
171:         Args.notNull(socketPath, "Unix domain socket path");
172: 
